"""Independent L19 versioned repair and gap gate with prior exposure disclosure."""
from pathlib import Path
import copy,datetime,hashlib,json,sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'scripts'))
from validate import question_hash,schema_errors,validate_bank
read=lambda p:json.loads((ROOT/p).read_text())
sha=lambda p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest()
def write(p,v):(ROOT/p).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
now=datetime.datetime.now(datetime.timezone.utc).isoformat();R='define_robotics_data_contracts:L19-independent-reviewer'
ap='audits/blind-answers-W04-L19-v2-contracts-reviewer.json';assert sha(ap)=='c3eba79aa39bce143c73d9dfb0906236e7864477a0b76b40c2ff0490db06ceca'
e=read(ap);m=read('audits/W04-L19-v2-review-manifest.json');reveal=read('audits/W04-L19-v2-contracts-author-reveal.json')
assert e['answersFrozenAt']<reveal['revealedAt'];assert sha(reveal['snapshotPath'])==reveal['batchSha256'];assert sha(e['blindPacketPath'])==e['blindPacketSha256']==m['blindPacketSha256']
b=read(reveal['snapshotPath']);old=read('audits/review-snapshots/W04-L19-v1-contracts.json');oldqs={q['id']:q for q in old['questions']};qs={q['id']:q for q in b['questions']};answers={a['questionId']:a for a in e['independentAnswers']}
prior=read('data/reviews/W04-L19-v1-independent-contracts.json');accepted=[rv for rv in prior if rv['decision']=='verified'];assert len(accepted)==71
assert {rv['questionId'] for rv in accepted}==set(m['preservedAcceptedHashes'])
for rv in accepted:
 q=qs[rv['questionId']];assert question_hash(q)==question_hash(oldqs[q['id']])==rv['questionSha256']==m['preservedAcceptedHashes'][q['id']]
obs={o['physicalPage']:o for o in e['sourceObservations']};obs.update({o['physicalPage']:o for o in e['sourceReinspections']})
for o in obs.values():assert sha(o['previewPath'])==o['previewSha256']
flags={
'W04-L19-P0598-Q04':[('distractors','The revised o2 says the wheel radius physically increases without changing the wheels, and o3 says ground-contact support points relocate while those same contacts remain fixed. These remain self-contradictory or physically implausible rather than credible alternatives. Replace them with finite performance/design misconceptions about load redistribution, obstacle negotiation, clearance or traction. Keep the correctly scoped source claim and distinguish changing load distribution from changing contact geometry.')],
'W04-L19-P0602-Q02':[('distractors','The revision still assigns facility-scale relocation to the arm in both o2 and o3, which is not a credible competing gross/fine allocation for a bounded arm. Remove the facility-scale phrase from false arm-role alternatives and use plausible competing allocations within the arm/base workspace, such as swapping local fine corrections and larger within-reach movements, or assuming one component remains fixed for every phase. Ask specifically for the source-emphasized division so alternatives need not claim physically impossible motion.')]
}
reviews=[]
for qid,a in answers.items():
 q=qs[qid];assert question_hash(q)==a['questionSha256']==m['questionSha256'][qid];assert set(q['correctOptionIds'])==set(a['answerOptionIds']);assert R not in {q['authorId'],*q.get('revisionAuthors',[])}
 fresh=q['version']==1;pages=sorted(set(c['physicalPage'] for c in q['citations']));checks={k:True for k in ['sourceSupport','assumptions','answerSet','distractors','calculations','figureFidelity','explanation','difficulty','duplication']}
 for criterion,_ in flags.get(qid,[]):checks[criterion]=False
 reason=a['reasoning']+' All nine criteria were checked against the exact current object, including every option rationale, relevant formula definitions/units and source qualifications. The original 28-page actual-pixel record is retained; seven relevant source pages were reinspected. Twenty-nine new reviewer-owned assertions and 300 randomized paired-section comparisons passed before current keyed access. All 71 previously accepted objects retain their correctness hashes. '+('This new beam question was solved from the actual source formulas and fresh answer-free packet before any proposed key or solution was seen.' if fresh else 'I previously saw the v1 key and solution, so solvedBeforeAnswerSeen is false. Current-version answers, including the new two-encoder numerical application, were still derived and frozen before opening current keyed objects.')+' '+('The remaining distractor defect prevents approval despite the correct intended key.' if qid in flags else 'The prior findings for this object are closed; all nine criteria pass. This is not a complete-course coverage claim.')
 reviews.append(dict(id=qid+f'-v{q["version"]}-contracts-independent',questionId=qid,questionVersion=q['version'],questionSha256=question_hash(q),reviewerId=R,decision='flagged' if qid in flags else 'verified',reviewedAt=now,sourceVersions=e['sourceVersions'],reviewedSlideIds=[f'lectures-p{p:04}' for p in pages],independentAnswerOptionIds=a['answerOptionIds'],solvedBeforeAnswerSeen=fresh,checks=checks,reasoning=reason,findings=[msg for _,msg in flags.get(qid,[])],blindAnswersPath=ap,blindAnswersSha256=sha(ap),independentSolvedAt=e['answersFrozenAt'],priorAuthorExposure=not fresh,exposureDisclosure='No prior question-author exposure for this new question.' if fresh else 'Prior v1 key and solution exposure; current-version response frozen before current keyed access.',computationsPath=e['computationsPath'],sourceInspectionEvidence=[dict(inspectorId=R,**{k:obs[p][k] for k in ['physicalPage','previewPath','previewSha256','dimensions','inspectedAt']}) for p in pages]))
assert len(reviews)==29 and sum(rv['solvedBeforeAnswerSeen'] for rv in reviews)==1
errors=[x for rv in reviews for x in schema_errors(rv,read('data/schema.review.json'))];assert not errors,errors
out='data/reviews/W04-L19-v2-independent-contracts.json';write(out,reviews)
allreviews=accepted+reviews;rb={rv['questionId']:rv for rv in allreviews};current=copy.deepcopy(b['questions']);cs=copy.deepcopy(b['concepts'])
for q in current:q['status']=rb[q['id']]['decision'];q['reviewIds']=[rb[q['id']]['id']]
verified={q['id'] for q in current if q['status']=='verified'}
for c in cs:c['status']='verified' if any(qid in verified for qid in c['questionIds']) else 'drafted'
sm=read('sources/manifest.json');slides=[json.loads(line) for sid in ['lectures','assignments'] for line in (ROOT/f'sources/page_maps/{sid}.jsonl').read_text().splitlines()];updates={v['id']:v for v in read('data/inspection-batches/W04-L19.json')['slides']};slides=[copy.deepcopy(updates.get(v['id'],v)) for v in slides]
for slide in slides:
 if slide['id'] in updates:slide['conceptIds']=[c['id'] for c in cs if slide['id'] in c['slideIds']]
tmp={'schemaVersion':'1.0.0','bankVersion':'L19-v2-independent-isolated','title':'L19 repair and gap validation','complete':False,'sources':sm['sources'],'assets':sm['assets'],'slides':slides,'questions':current,'concepts':cs,'reviews':allreviews,'learningTools':{k:[] for k in ['formulaSheet','confusionPairs','traps','algorithmVisualizations','numericalFamilies']}}
v=validate_bank(tmp,ROOT,check_files=True)
summary={'reviewerId':R,'completedAt':now,'currentSliceReviewed':29,'repairsAccepted':26,'newGapsAccepted':1,'flagged':2,'keyDisagreements':0,'previousAcceptedHashesPreserved':71,'currentLectureVerified':len(verified),'currentLectureTotal':len(current),'priorActualPagesInspected':28,'currentActualPageReinspections':7,'newIndependentAssertions':29,'randomTrials':300,'reviewFile':out,'reviewSha256':sha(out),'answerEvidencePath':ap,'answerEvidenceSha256':sha(ap),'flaggedQuestionIds':list(flags),'findings':[{'questionId':qid,'criteria':[c for c,_ in fs],'findings':[msg for _,msg in fs]} for qid,fs in flags.items()],'exposure':'Twenty-eight repair reviews disclose prior v1 key/solution exposure; only the new paired beam gap is first-exposure blind. All current-version responses were frozen before current keyed content.','coverageChallenge':[{'id':'L19-COVERAGE-01','status':'closed_by_verified_question','questionId':'W04-L19-P0592-Q09','version':1,'detail':'The full round/square fixed-tip-load stiffness and deflection calculation is source-bound and independently matches both values and all numerical distractors.'},{'id':'L19-COVERAGE-02','status':'closed_by_verified_repair','questionId':'W04-L19-P0588-Q03','version':2,'detail':'The paired lead/ball-screw item now tests the source-specific stiffness/load/friction/backdrive tradeoff.'},{'id':'L19-COVERAGE-03','status':'bounded_accounting_note','detail':'Original all-page inspection and source qualifications are retained; closure of the identified gaps is not proof of complete-course assessment.'}],'validation':v,'mutations':'Reviewer audits, checks, reviews and handoff only; no author question, bank, source or Git edits.'}
write('audits/W04-L19-v2-contracts-review-summary.json',summary)
(ROOT/'docs/handoffs/L19-v2-contracts-review.md').write_text(f'# L19 v2 review frozen\n\n26 repairs plus the new beam gap pass; two distractor-quality findings remain. All 71 accepted v1 hashes are unchanged, yielding 98 verified of 100 current questions. No key disagreements. The new two-encoder numerical application gives 0.01 rad and 200 N m/rad; the paired beam deflections are 0.0169765273 mm and 0.0100000000 mm.\n\nReview: {out}, SHA256 {sha(out)}. Exact remaining findings and isolated validation: audits/W04-L19-v2-contracts-review-summary.json. Evidence: {ap}. Twenty-eight repairs disclose prior exposure; only the new gap is first-exposure blind. Seven source pages were reinspected, with all original 28-page observations retained. Twenty-nine independent assertions and 300 random paired-section trials passed.\n\nRemaining flags: P0598-Q04 still uses self-contradictory wheel-radius/contact-location distractors; P0602-Q02 still assigns facility-scale relocation to a bounded arm. Preserve the 98 accepted hashes while revising these two objects. Both previously identified coverage gaps are closed. No bank or Git edits. Await the two-item versioned packet or next parent assignment.\n')
print(json.dumps({k:summary[k] for k in ['repairsAccepted','newGapsAccepted','flagged','currentLectureVerified','currentLectureTotal','reviewSha256','validation']},indent=2));assert v['valid'],v
